const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const progress=document.querySelector('.scroll-progress');let frame=0;
addEventListener('scroll',()=>{if(frame)return;frame=requestAnimationFrame(()=>{const max=document.documentElement.scrollHeight-innerHeight;progress.style.width=`${max>0?scrollY/max*100:0}%`;frame=0})},{passive:true});
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08,rootMargin:'0px 0px -30px'});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
const menu=document.querySelector('.menu-button'),nav=document.querySelector('.site-header nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu');nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
if(!reduced&&matchMedia('(pointer:fine)').matches)document.querySelectorAll('[data-tilt]').forEach(card=>{card.addEventListener('pointermove',e=>{const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;card.style.transform=`perspective(900px) rotateX(${-y*3}deg) rotateY(${x*3}deg) translateY(-3px)`});card.addEventListener('pointerleave',()=>card.style.transform='')});
function downloadProfile(){const html=`<!doctype html><html lang="en"><meta charset="utf-8"><title>Erfan Mohiti — Professional Profile</title><style>body{font-family:Arial,sans-serif;max-width:800px;margin:50px auto;padding:35px;color:#10251d;line-height:1.7}h1{font-size:38px;margin-bottom:0}h2{font-size:20px;margin-top:32px;border-bottom:1px solid #bad1c6;padding-bottom:7px}small{color:#5b756a}li{margin:8px 0}@media print{body{margin:0}}</style><h1>Erfan Mohiti</h1><p>Maxillofacial Prosthesis Designer at Farin Roshaan</p><small>Design experience across more than 400 patient cases</small><h2>Areas of expertise</h2><ul><li>Aesthetic implants: mandibular angle, chin and cheek</li><li>Therapeutic prostheses: partial mandible, TMJ, cranial and orbital floor</li><li>Subperiosteal prostheses</li><li>Surgical guides, including fibula guides</li></ul><h2>Software and surgical planning</h2><p>Prosthesis and guide design in FreeForm; analysis of orthognathic surgery candidates in ProPlan; surgical simulation; and design and production of intermediate and final splints.</p><h2>Additive manufacturing</h2><p>Hands-on experience with DLP, filament and PEEK printers.</p><h2>Organization</h2><p>Farin Roshaan — https://farinroshaan.com/</p>`;const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='Erfan-Mohiti-Professional-Profile.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
document.querySelector('#resume-button').addEventListener('click',downloadProfile);document.querySelector('#year').textContent=new Date().getFullYear();
const heroTarget=document.querySelector('#hero-model'),labTarget=document.querySelector('#stl-viewer');let modulePromise;const load3D=()=>modulePromise||=import('./viewer.js');
const heroObserver=new IntersectionObserver(async entries=>{if(entries.some(e=>e.isIntersecting)){heroObserver.disconnect();try{const{initHero}=await load3D();initHero(heroTarget,reduced)}catch(e){heroTarget.querySelector('.model-loading').textContent='3D preview is unavailable in this browser';console.warn(e)}}},{rootMargin:'150px'});heroObserver.observe(heroTarget);
const labObserver=new IntersectionObserver(async entries=>{if(entries.some(e=>e.isIntersecting)){labObserver.disconnect();try{const{initLab}=await load3D();initLab(labTarget,reduced)}catch(e){labTarget.querySelector('.viewer-loading').textContent='The STL viewer is unavailable in this browser';console.warn(e)}}},{rootMargin:'200px'});labObserver.observe(labTarget);
